function handler({api, event, helpers, imports}) {
    var stagingSysId = api.context.props.sysparm_staging_id || api.context.props.sys_id;
    if (!stagingSysId || stagingSysId === '') {
        var pathParts = window.location.pathname.split('/');
        stagingSysId = pathParts[pathParts.length - 1];
    }

    var newPassword = api.state.newPassword; 

    if (!stagingSysId || !newPassword) {
        helpers.snMessaging.showToast({
            type: 'error',
            message: 'Please enter a password.'
        });
        return;
    }

    fetch('/api/x_travel_buddy_app/password_management_api/update', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'Accept': 'application/json',
            'X-UserToken': window.g_ck || ''
        },
        body: JSON.stringify({
            "staging_sys_id": stagingSysId,
            "password": newPassword
        })
    })
    .then(function(response) {
        return response.json();
    })
    .then(function(data) {
        var res = data.result || data;
        if (res.success) {
            helpers.snMessaging.showToast({
                type: 'success',
                message: 'Password created successfully!'
            });
        } else {
            helpers.snMessaging.showToast({
                type: 'error',
                message: res.message || 'Failed to update password.'
            });
        }
    })
    .catch(function(error) {
        console.error('Error submitting password:', error);
    });
}
